import {LANE_COLORS,traitRelations,layoutTraits,layoutLineages,edgePath,graphControls,graphSurface,arrows} from './graphs.js';
import {GENES,TRAITS,TRAIT_INDEX,STAGES,SOURCES,LANES,has} from './biology.js';
export const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function direction(s){const modes=[{i:0,label:'光能利用'},{i:1,label:'化能利用'},{i:2,label:'捕食倾向'}].sort((a,b)=>s.mean[b.i]-s.mean[a.i]);return modes[0].label;}
export function inspector(world,selected,individualId=null){
 const s=world.species.find(s=>s.id===selected),record=world.records[individualId];
 if(!s)return `<h3>没有终点的生命世界</h3><p>点击生命，固定追踪一个个体。它的身体、亲本与后代会留下可查证的记录。</p><div class="mini-stats"><span><b>${world.totalBirths}</b>出生</span><span><b>${world.totalCrossovers}</b>交叉</span><span><b>${world.totalDeaths}</b>死亡</span></div>${world.saturated?'<p class="warning">已达到 2,200 个体的计算上限，模拟暂停。这不是生态平衡。</p>':''}`;
 const biggest=s.mean.map((v,i)=>({i,delta:v-s.founder[i]})).sort((a,b)=>Math.abs(b.delta)-Math.abs(a.delta))[0];
 const specimenId=record?record.id:s.specimen?.id;
 return `<div class="section-heading"><h3 style="color:${s.color}">${escape(s.name)}</h3><span class="muted">${s.count?(s.splitCandidate?'分群观察中':'存续'):'历史支系'}</span></div><p>${record?`固定追踪 #${record.id}，${record.death?'个体已死亡，保留其遗传与家系档案。':'世界继续演进，追踪对象保持不变。'}`:s.count?`当前基因倾向：${direction(s)}。${GENES[biggest.i].name}相对起源${biggest.delta>=0?'增加':'减少'}了 ${Math.abs(biggest.delta*100).toFixed(1)} 点。`:`登记支系的最后一个个体消失于 T + ${s.extinct}。`}</p>${s.parent?`<p class="ancestry-note">T + ${s.born} 从 ${escape(world.species.find(p=>p.id===s.parent).name)} 登记分支。分类名称不决定繁殖兼容性。</p>`:''}${specimenId?`<button class="specimen-window" data-individual="${specimenId}" data-inspect="individual:${specimenId}" aria-label="放大观察个体 ${specimenId}"><span class="specimen-scale">${record?'固定个体':'当前代表个体'} #${specimenId} · 点击放大 ↗</span></button><button class="button subtle archive-entry" data-observe="${specimenId}">身体、亲缘与证据 ↗</button>`:''}<div class="mini-stats"><span><b>${s.births}</b>登记出生</span><span><b>${s.deaths}</b>登记死亡</span><span><b>${Math.round(s.diversity*100)}</b>基因差异</span></div><details class="gene-details" ${s.count?'open':''}><summary>群体遗传画像 <small>浅线 = 起源均值</small></summary><div class="gene-list">${GENES.map((g,i)=>`<div class="gene-row"><span>${g.name}</span><div class="gene-bar"><i style="width:${s.mean[i]*100}%;background:${g.color}"></i><em style="left:${s.founder[i]*100}%"></em></div><b>${Math.round(s.mean[i]*100)}</b></div>`).join('')}</div></details><div class="death-causes">${Object.entries(s.deathCauses).map(([k,v])=>`<span>${k} ${v}</span>`).join('')}</div>`;
}
export function traitView(world,selected,traitId='pigment',lane='all',query='',mode='path',zoom=1){
 const species=world.species.find(s=>s.id===selected),group=world.agents.filter(a=>!selected||a.species===selected),discovered=new Set(world.species.filter(s=>!selected||s.id===selected).flatMap(s=>s.discovered));
 const counts=TRAITS.map(t=>group.filter(a=>has(a,t.id)).length),eligible=TRAITS.map(t=>group.some(a=>!has(a,t.id)&&a.genes[t.gene]>=t.min&&t.parents.every(p=>has(a,p))&&!(t.excludes||[]).some(p=>has(a,p))));
 const t=TRAITS[TRAIT_INDEX[traitId]],relation=traitRelations(t.id),next=TRAITS.filter(v=>v.parents.includes(t.id));
 const matches=TRAITS.filter(v=>(lane==='all'||v.lane===lane)&&(!query||[v.name,v.shape,v.effect].some(x=>x.includes(query))));
 const shown=new Set([t.id]);const filtered=query||lane!=='all';
 if(filtered||mode==='all')matches.forEach(v=>shown.add(v.id));else{relation.ancestors.forEach(id=>shown.add(id));if(mode==='path')next.forEach(v=>shown.add(v.id));}
 function includeParents(id){for(const p of TRAITS[TRAIT_INDEX[id]].parents)if(!shown.has(p)){shown.add(p);includeParents(p);}}
 [...shown].forEach(includeParents);const layout=layoutTraits(TRAITS.filter(v=>shown.has(v.id)).map(v=>v.id));
 const paths=layout.edges.map(e=>{const key=e.from+':'+e.to,kind=relation.before.has(key)?'before':relation.after.has(key)?'after':'neutral';return `<path class="graph-edge ${kind}" data-from="${e.from}" data-to="${e.to}" d="${edgePath(e.points)}" marker-end="url(#trait-${kind})"/>`;}).join('');
 const cards=layout.nodes.map(n=>{const v=TRAITS[TRAIT_INDEX[n.id]],i=TRAIT_INDEX[v.id],enabled=world.config.fiction||v.kind!=='fiction',state=!enabled?'disabled':counts[i]>0?'present':discovered.has(v.id)?'lost':eligible[i]?'possible':'unseen',related=n.id===t.id||relation.ancestors.has(n.id)||relation.descendants.has(n.id);return `<button class="graph-node trait-card ${state} ${n.id===t.id?'selected':''} ${related?'path-node':''}" data-trait="${v.id}" data-node-id="${v.id}" data-x="${n.x}" data-y="${n.y}" data-w="${n.width}" data-h="${n.height}" style="left:${n.x-n.width/2}px;top:${n.y-n.height/2}px;width:${n.width}px;height:${n.height}px;--node-color:${LANE_COLORS[v.lane]}" aria-pressed="${n.id===t.id}"><span class="node-category">${LANES[v.lane]}<small>${String(v.stage+1).padStart(2,'0')}</small></span><strong>${v.name}</strong><span class="node-status">${!enabled?'科幻模式关闭':counts[i]?counts[i]+' 个体携带':discovered.has(v.id)?'曾有 · 当前消失':eligible[i]?'可发生突变':'未出现'}</span>${v.parents.length>1?`<span class="node-and">需 ${v.parents.length} 项前置</span>`:''}</button>`;}).join('');
 const graph=`<svg class="graph-lines" width="${layout.width}" height="${layout.height}" aria-hidden="true">${arrows('trait')}${paths}</svg>${cards}`;
 const details=`<aside class="path-detail"><span class="eyebrow">${t.kind==='fiction'?'科幻结构':'所选结构'} · ${STAGES[t.stage]}</span><h3>${t.name}</h3><button class="specimen-window" data-preview="trait:${t.id}" data-inspect="trait:${t.id}" aria-label="观察${t.name}的结构模型"><span class="specimen-scale">结构设想 · 点击放大</span></button><p>${t.description}</p><dl><dt>当前携带</dt><dd>${counts[TRAIT_INDEX[t.id]]} 个体 / ${group.length}</dd><dt>生态效果</dt><dd>${t.effect}</dd><dt>维护成本</dt><dd>${t.cost.toFixed(3)} / 时步</dd><dt>${t.parents.length>1?'以下前置需同时具备':'直接前置'}</dt><dd class="path-links">${t.parents.map(p=>`<button data-trait="${p}">${TRAITS[TRAIT_INDEX[p]].name} ↗</button>`).join('')||'原始复制结构'}</dd><dt>直接后续 · ${next.length}</dt><dd class="path-links">${next.map(v=>`<button data-trait="${v.id}">${v.name} ↗</button>`).join('')||'图谱中没有后续结构'}</dd><dt>基因门槛</dt><dd>${GENES[t.gene].name} ≥ ${Math.round(t.min*100)}</dd>${t.excludes?`<dt>当前模型中的互斥结构</dt><dd>${t.excludes.map(id=>TRAITS[TRAIT_INDEX[id]].name).join('、')}</dd>`:''}</dl></aside>`;
 return `<div class="view-intro"><div><span class="eyebrow">TRAIT DEPENDENCIES</span><h2>循着结构，读懂演化分支</h2><p>箭头从前置指向后续；多条入线表示需要共同具备。这里展示可能性，不代表真实祖先关系。</p></div><span class="scope-label">${species?escape(species.name):'全部谱系'}</span></div><div class="atlas-toolbar"><div class="lane-filters">${[['all','全部类别'],...Object.entries(LANES)].map(([id,label])=>`<button data-lane="${id}" class="${lane===id?'active':''}">${label}</button>`).join('')}</div><input id="trait-search" aria-label="搜索进化结构" placeholder="搜索结构或能力…" value="${escape(query)}"></div>${query?`<div class="search-results">${matches.map(v=>`<button class="inline-trait" data-trait="${v.id}">${v.name} ↗</button>`).join('')||'没有匹配结构'}</div>`:''}<div class="graph-modebar"><div class="graph-tabs">${[['path','前置与分支'],['ancestors','只看前置'],['all','完整图谱']].map(([id,name])=>`<button data-path-mode="${id}" class="${mode===id?'active':''}">${name}</button>`).join('')}</div><span>${layout.nodes.length} 个节点 · ${layout.edges.length} 条构建关系</span></div><div class="atlas-workspace"><section class="graph-panel">${graphControls('traits',zoom)}${graphSurface('traits',layout,zoom,graph)}<div class="graph-key"><span class="before">━ 前置路径</span><span class="after">━ 后续分支</span><span>拖动空白平移 · 箭头可连续追踪</span></div></section>${details}</div><p class="atlas-note">选择结构只用于观察。变异不会按点击的路径发生；结构需要支付成本，通过生存与繁殖接受选择。</p><button class="button subtle" data-open-lineage>查看本次世界的实际亲缘分支 ↗</button>`;
}
export function lineageView(world,selected,selectedNode=null,zoom=1){
 if(!world.lineages.length)return '<div class="view-intro"><h2>等待第一批生命诞生</h2></div>';
 const nodes=new Map(world.lineages.map(n=>[n.id,n])),species=new Map(world.species.map(s=>[s.id,s])),chosen=nodes.get(selectedNode)||nodes.get(species.get(selected)?.lineage)||nodes.get(world.lineages[0].id),layout=layoutLineages(world),related=new Set([chosen.id]),edgesOn=new Set();
 let current=chosen;while(current.parent!==null){edgesOn.add(current.parent+':'+current.id);related.add(current.parent);current=nodes.get(current.parent);}
 function descendants(n){for(const id of n.children){related.add(id);edgesOn.add(n.id+':'+id);descendants(nodes.get(id));}}if(chosen.children.length)descendants(chosen);
 const lines=layout.edges.map(e=>`<path class="graph-edge ${edgesOn.has(e.from+':'+e.to)?'before':'neutral'}" d="${edgePath(e.points)}" marker-end="url(#family-${edgesOn.has(e.from+':'+e.to)?'before':'neutral'})"/>`).join('');
 const exchanges=new Map();
 for(const flow of world.geneFlows){if(!flow.species.includes(chosen.species))continue;const pair=[...flow.species].sort((a,b)=>a-b),key=pair.join(':');if(!exchanges.has(key))exchanges.set(key,{pair,count:0,last:flow.tick,child:flow.child});const e=exchanges.get(key);e.count++;e.last=flow.tick;e.child=flow.child;}
 const exchangeList=[...exchanges.values()].sort((a,b)=>b.count-a.count),extended={...layout,width:layout.width+(exchangeList.length?100:0)};
 const exchangeLines=exchangeList.map((e,i)=>{const a=layout.nodes.find(n=>n.id===species.get(e.pair[0]).lineage),b=layout.nodes.find(n=>n.id===species.get(e.pair[1]).lineage),right=Math.max(a.x+a.width/2,b.x+b.width/2)+28+(i%4)*14;return `<path class="gene-flow-edge" d="M${a.x+a.width/2},${a.y} C${right},${a.y} ${right},${b.y} ${b.x+b.width/2},${b.y}"><title>${escape(species.get(e.pair[0]).name)} ↔ ${escape(species.get(e.pair[1]).name)} · ${e.count} 次跨分群出生</title></path>`;}).join('');
 const cards=layout.nodes.map(n=>{const node=nodes.get(n.id),s=species.get(node.species),split=node.children.length;return `<button class="graph-node family-node ${split?'fork-node':''} ${chosen.id===n.id?'selected':''} ${related.has(n.id)?'path-node':''} ${!split&&!s.count?'extinct':''}" data-lineage-node="${n.id}" data-node-id="${n.id}" data-x="${n.x}" data-y="${n.y}" data-w="${n.width}" data-h="${n.height}" style="left:${n.x-n.width/2}px;top:${n.y-n.height/2}px;width:${n.width}px;height:${n.height}px;--node-color:${s.color}"><span class="node-category">${split?'⑂ 实际分叉':'L'+n.id+' · '+(s.count?'存续':'灭绝')}</span><strong>${split?'祖支 L'+n.id:escape(s.name)}</strong><span class="node-status">${split?'T + '+node.split:s.count+' 个体 · G'+s.generation}</span></button>`;}).join('');
 const roots=layout.roots.map(r=>`<div class="forest-caption" style="top:${r.y}px;left:36px">◎ 独立起源 · ${escape(species.get(r.species).name.split(' · ')[0])}</div>`).join('');
 const s=species.get(chosen.species),ancestor=nodes.get(chosen.parent)?.snapshot,a=chosen.children.length?chosen.snapshot:s.specimen,added=a&&ancestor?a.traits.filter(id=>!ancestor.traits.includes(id)):[],lost=a&&ancestor?ancestor.traits.filter(id=>!a.traits.includes(id)):[];
 const fork=chosen.children.length?chosen:nodes.get(chosen.parent),evidence=fork?.children.map(id=>species.get(nodes.get(id).species)).find(child=>child.born===fork.split&&child.parent===fork.species)?.speciationEvidence;
 const details=`<aside class="path-detail"><span class="eyebrow">${chosen.children.length?'分叉前的观测':'真实代表个体'}</span><h3>${chosen.children.length?'祖支 L'+chosen.id:escape(s.name)}</h3>${a?`<button class="specimen-window" ${chosen.children.length?`data-ancestor="${chosen.id}" data-inspect="ancestor:${chosen.id}"`:`data-model="${s.id}" data-inspect="species:${s.id}"`} aria-label="观察所选谱系标本"><span class="specimen-scale">点击比较外观与解剖</span></button>`:''}<dl><dt>分支起点</dt><dd>T + ${chosen.born}</dd><dt>${chosen.children.length?'分化时点':'当前状态'}</dt><dd>${chosen.children.length?'T + '+chosen.split:s.count?s.count+' 个体，最高 '+s.generation+' 代':'T + '+s.extinct+' 灭绝'}</dd><dt>直接祖支</dt><dd>${chosen.parent?`<button class="inline-trait" data-lineage-node="${chosen.parent}">L${chosen.parent} ↗</button>`:'独立起源'}</dd>${chosen.children.length?`<dt>两个延续方向</dt><dd class="path-links">${chosen.children.map(id=>`<button data-lineage-node="${id}">支系 L${id} ↗</button>`).join('')}</dd>`:''}${evidence?`<dt>这次分叉的记录</dt><dd>${evidence.cohort} 个体 · 均值差 ${evidence.gap.toFixed(3)}</dd>`:''}<dt>相对上一个祖先快照</dt><dd>${added.length?'新增 '+added.map(id=>TRAITS[TRAIT_INDEX[id]].name).join('、')+'。':''}${lost.length?'丢失 '+lost.map(id=>TRAITS[TRAIT_INDEX[id]].name).join('、')+'。':''}${!ancestor?'独立起源，无上一祖先快照。':!added.length&&!lost.length?'代表个体没有结构增减；连续基因仍可分化。':''}</dd></dl><p>快照保存当时的代表个体，不能代表祖先群体中的全部变异。</p>${!chosen.children.length?`<button class="text-button" data-follow="${s.id}">追踪该种群 ↗</button>`:''}</aside>`;
 const exchangesPanel=`<section class="archive-panel"><div class="section-heading"><h2>分支之间，仍可能有交流</h2><span class="muted">所选分群 · 累计出生记录</span></div><p>实线保留登记分支的历史，金色虚线连接发生过双亲交叉的分群。线连接当前登记节点，具体发生时刻与个体见下面的出生记录。</p>${exchangeList.length?`<div class="exchange-list">${exchangeList.map(e=>`<div><span>${e.pair.map(id=>escape(species.get(id).name)).join(' ↔ ')}</span><strong>${e.count} 次</strong><button class="text-button" data-observe="${e.child}">最近后代 #${e.child} · T + ${e.last} ↗</button></div>`).join('')}</div>`:'<p>尚未记录所选分群与其他标签之间的成功交叉。这本身不能证明生殖隔离。</p>'}${evidence?`<details><summary>登记时的分化依据</summary><p>${escape(evidence.status)} · 持续观察 ${evidence.tick-evidence.since} 时步，分群内有 ${evidence.newborns} 个存活新生个体，来自 ${evidence.contributors} 个亲本。遗传均值距离 ${evidence.gap.toFixed(3)}。</p><p>跨分群潜在个体配对中 ${evidence.compatiblePairs} / ${evidence.totalPairs} 对通过遗传识别规则。繁殖尝试中记录 ${evidence.encounters.encounters} 次近邻相遇，${evidence.encounters.births} 次成功出生。计数来自登记时仍存活成员的历史尝试，不是独立样本数，也不是全部物理接触。</p><p>“识别屏障”只说明当前模型的交配前条件；空间分离、无性分化和完整生物物种的界定需要分别解释。</p></details>`:''}</section>`;
 return `<div class="view-intro"><div><span class="eyebrow">RECORDED LINEAGES / OBSERVED EXCHANGE</span><h2>分支留在历史，生命继续交流</h2><p>沿亮线追溯共同来源。分群是观察记录，是否交配由个体的遗传识别与相遇条件决定。</p></div></div><div class="lineage-stats"><span><b>${world.lineages.filter(n=>n.children.length).length}</b> 次分支登记</span><span><b>${world.species.filter(s=>s.count).length}</b> 条存续支系</span><span><b>${world.geneFlows.length}</b> 次跨分群出生</span></div><div class="atlas-workspace lineage-workspace"><section class="graph-panel">${graphControls('lineage',zoom)}${graphSurface('lineage',extended,zoom,`<svg class="graph-lines" width="${extended.width}" height="${layout.height}" aria-hidden="true">${arrows('family')}${lines}${exchangeLines}</svg>${roots}${cards}`)}<div class="graph-key"><span class="before">━ 所选来源路径</span><span class="exchange-key">┄ 跨分群交叉</span><span>按登记次序排布 · 线长不代表时间</span>${world.species.length>=40?'<span class="capacity-note">已达 40 个历史分群，后续分化不再登记</span>':''}</div></section>${details}</div>${exchangesPanel}`;
}
export function journalView(world,filter='all',limit=80){
 const events=world.timeline.filter(e=>filter==='all'||(filter==='biology'?['trait','speciation','extinction','origin'].includes(e.type):['environment','settings','capacity'].includes(e.type))).slice().reverse();
 const shown=events.slice(0,limit);
 return `<div class="view-intro"><div><span class="eyebrow">FIELD NOTES</span><h2>世界仍在书写</h2><p>关键事件长期保存在世界档案里。出生与死亡记录留在每个个体的生命档案中。</p></div></div><div class="journal-summary"><div><strong>${world.totalBirths}</strong><span>累计出生</span></div><div><strong>${world.totalCrossovers}</strong><span>双亲交叉</span></div><div><strong>${world.geneFlows.length}</strong><span>跨分群出生</span></div><div><strong>${Object.keys(world.records).length}</strong><span>个体档案</span></div></div><div class="journal-tabs" role="group" aria-label="事件筛选">${[['all','全部记录'],['biology','生命演变'],['environment','环境变化']].map(([id,label])=>`<button data-filter="${id}" class="${filter===id?'active':''}">${label}</button>`).join('')}</div><div class="event-list">${shown.map(e=>`<article class="journal-event"><span class="event-time">T + ${String(e.tick).padStart(6,'0')}</span><div class="event-icon ${e.type}">${({trait:'◇',speciation:'⑂',extinction:'×',environment:'≋',origin:'◎',settings:'⊙',capacity:'Ⅱ'})[e.type]}</div><div><h3>${escape(e.title)}</h3><p>${escape(e.detail)}</p>${e.speciesId?`<button data-follow="${e.speciesId}" class="text-button">追踪谱系 ↗</button>`:''}</div></article>`).join('')||'<p class="empty-copy">这个世界还没有发生此类事件。</p>'}</div>${events.length>shown.length?`<button class="button subtle" data-more-events>更早的记录 · 已显示 ${shown.length} / ${events.length}</button>`:''}`;
}
export function guideView(){return `<div class="dialog-top"><h2>观察一个持续演进的世界</h2><button class="close-button" data-close aria-label="关闭说明">×</button></div><div class="guide-grid"><section><h3>生命与它的来处</h3><p>地图上的生命由实际个体组成。点击一个个体固定追踪，再进入生命档案查看身体、父母、后代和能量记录。打开档案与说明时世界继续运行；暂停与快进由你控制。</p><p>种群的代表标本会随群体组成改变，个体档案则始终指向同一 ID。历史标本保存出生时的遗传形态；等大比较不表示两者体型相同，可切换为同一比例。</p><h3>改变世界的条件</h3><p>温度、光照、地质补给、海平面与即时事件会影响同一个生态系统。突变率设置改变随机变异的概率，不指定变异方向。关键干预与事件保存在世界档案中。</p><p>可在观测记录保存快照，自选一个环境变化运行三次独立配对对照。分支拥有自己的历史和结果，不写回当前世界。结果范围来自少量重复，不是置信区间。</p></section><section><h3>遗传与身体</h3><p>个体携带 12 个生态参数、8 个形态参数、繁殖与识别参数，以及有限的结构能力。连续参数在交叉和出生变异中改变；结构按依赖模块重组，新增和丢失采用相同的尝试概率，但可用结构与依赖清除仍会造成偏置。</p><p>身体比例、推进与保护结构同时改变外形和模型中的功能、维护成本。体色与斑纹目前只影响外观。动作、模型尺度和结构面积是解释性示意，未计算真实流体力学或胚胎发育。</p><h3>分群与繁殖</h3><p>分类标签只记录观察结果。不同标签的个体仍可能交叉；交配取决于起源体系、繁殖方式、识别信号、能量、成熟程度与接触机会。协作使用独立的社会识别信号，捕食依据摄食能力和体型等条件。</p><p>有性个体需要兼容配偶；无性个体单亲复制；兼性个体可以采用两种方式。识别模型只表达交配前屏障，不包含杂交后代不育。没有相遇记录不能作为生殖隔离的证据。分支图保留历史，交流线表示真实的跨分群出生。</p></section></div><section class="model-note"><h3>模型边界</h3><p>生命起源是初始复制者生成，不是化学起源模拟。时步和世代不对应地球年代。${TRAITS.length} 项结构与前置关系构成有限的发育空间，不能保证无限演化，也不预设复杂化目标。组合实验台中的设想标本与真实生命分别标明。</p><p>光与化学能源合成都受能源和养分限制；摄食转移能量，死亡与未同化部分进入残骸，消耗散热并释放养分。所有有机物采用统一抽象养分比例，氧气仅是简化反馈；背景浮游物与分解过程目前是资源方程。</p><p>v5 存档保存完整世界、独立环境随机状态和个体证据，可精确续跑。旧版本存档需在对应原版本打开。达到 2,200 个体会明确暂停；历史分类最多 40 个，容量不是生态平衡。存档大小会随历史增长。</p></section><section class="sources"><h3>研究与模型依据</h3>${SOURCES.map(s=>`<a href="${s.url}" target="_blank" rel="noreferrer">${s.title} ↗</a><p>${s.note}</p>`).join('')}</section>`;}
